// Shared harness for the R07 front-end tests: a small DOM, the Server's real responses (generated by the
// storage tests into scripts/fixtures/r07) and a fake transport that answers like the Server does.
'use strict';
const fs = require('node:fs'), path = require('node:path');
const C = require('../../web/static/network-quality-core.js');
const UI = require('../../web/static/network-quality.js');
const State = require('../../web/static/agent-state.js');
globalThis.AgentState = State;
const Management = require('../../web/static/management.js');

const fixtureDir = path.join(__dirname, '..', 'fixtures', 'r07');
const load = name => JSON.parse(fs.readFileSync(path.join(fixtureDir, name + '.json'), 'utf8'));
const clone = v => JSON.parse(JSON.stringify(v));
const flush = async () => { for (let i = 0; i < 14; i++) await new Promise(resolve => setImmediate(resolve)); };
const AGENT = 'f1f1f1f1f1f1f1f1f1f1f1f1f1f1f1f1';

function dom() {
  const doc = {hidden: false, activeElement: null, listeners: new Map()};
  class Element {
    constructor(tag) {
      this.tagName = tag.toUpperCase(); this.children = []; this.dataset = {}; this.attrs = {}; this.style = {}; this.listeners = new Map();
      this.isConnected = true; this.value = ''; this.className = ''; this.hidden = false; this.ownText = ''; this.rect = {top: 10, bottom: 100, left: 10, right: 200, width: 190, height: 90};
    }
    set textContent(v) { this.ownText = String(v); this.children = []; }
    get textContent() { return this.ownText + this.children.map(c => c.textContent).join(''); }
    setAttribute(k, v) { this.attrs[k] = String(v); }
    getAttribute(k) { return this.attrs[k]; }
    append(...nodes) { for (const n of nodes) { if (n.parent) n.parent.children = n.parent.children.filter(x => x !== n); n.parent = this; this.children.push(n); } }
    get firstElementChild() { return this.children[0] || null; }
    get lastElementChild() { return this.children.at(-1) || null; }
    get parentNode() { return this.parent || null; }
    get nextElementSibling() { const a = this.parent?.children || []; return a[a.indexOf(this) + 1] || null; }
    insertBefore(node, before) {
      if (node === before) return node;
      if (node.parent) node.parent.children = node.parent.children.filter(n => n !== node);
      node.parent = this; node.isConnected = true;
      const i = before ? this.children.indexOf(before) : -1;
      if (i < 0) this.children.push(node); else this.children.splice(i, 0, node);
      return node;
    }
    contains(n) { return n === this || this.children.some(c => c.contains(n)); }
    replaceChildren(...nodes) { if (this.contains(doc.activeElement)) doc.activeElement = doc.body; this.ownText = ''; this.children = []; this.append(...nodes); }
    remove() { if (this.parent) this.parent.children = this.parent.children.filter(n => n !== this); this.isConnected = false; }
    addEventListener(t, f) { const a = this.listeners.get(t) || []; a.push(f); this.listeners.set(t, a); }
    removeEventListener(t, f) { this.listeners.set(t, (this.listeners.get(t) || []).filter(x => x !== f)); }
    dispatch(t, event = {}) { for (const f of this.listeners.get(t) || []) f({target: this, currentTarget: this, preventDefault() {}, ...event}); }
    click() { if (this.disabled) return; this.focus(); this.dispatch('click'); }
    // Like a browser: a disabled or hidden control (or one inside a hidden parent) cannot take the focus.
    focus() { if (this.disabled || this.hidden || this.parent?.hidden) return; doc.activeElement = this; }
    setSelectionRange() {}
    showModal() { this.open = true; }
    close() { this.open = false; this.dispatch('close'); }
    getBoundingClientRect() { return this.rect; }
    querySelectorAll(selector) {
      const all = this.children.flatMap(n => [n, ...n.querySelectorAll('*')]);
      return all.filter(n => selector === '*' || selector.split(',').some(s => {
        s = s.trim();
        if (s.startsWith('.')) return n.className.split(' ').includes(s.slice(1));
        if (s.startsWith('[data-')) {
          const m = s.match(/\[data-([^=]+)="([^"]+)"\]/); if (!m) return false;
          return n.dataset[m[1].replace(/-([a-z])/g, (_, c) => c.toUpperCase())] === m[2];
        }
        return s === n.tagName.toLowerCase();
      }));
    }
    querySelector(s) { return this.querySelectorAll(s)[0]; }
    all() { return this.children.flatMap(c => [c, ...c.all()]); }
  }
  doc.body = new Element('body');
  doc.createElement = t => new Element(t);
  const dialog = new Element('dialog'); doc.body.append(dialog); doc.querySelector = () => dialog;
  doc.addEventListener = (t, f) => { const a = doc.listeners.get(t) || []; a.push(f); doc.listeners.set(t, a); };
  doc.removeEventListener = (t, f) => doc.listeners.set(t, (doc.listeners.get(t) || []).filter(x => x !== f));
  doc.dispatch = (t, event = {}) => { for (const f of doc.listeners.get(t) || []) f(event); };
  return {doc, dialog};
}

// A card-history answer for one target, shaped like the Server's v3/card-history.
function cardHistory(target, now = 1800000000000) {
  const metric = target.protocol === 'tcp' ? 'pure_connect' : 'echo_rtt', revision = '2';
  const first = Math.floor(now / 300000) * 300000 - 11 * 300000;
  const stats = {count: 2, valid_rtts: 2, probe_attempts: 2, probe_successes: 2, connect_attempts: 2, connect_successes: 2, not_executed: 0, categories: {success: 2}, sent: 6, received: 6, p50_ms: 20, p95_ms: 30, jitter_ms: 0, jitter_pairs: 1, completeness: 'complete', execution_coverage: 'unverified'};
  const points = Array.from({length: 12}, (_, i) => ({...stats, start: first + i * 300000, end: first + (i + 1) * 300000, config_revision_min: revision, config_revision_max: revision, slot_revision_min: target.slot_revision, slot_revision_max: target.slot_revision}));
  const sample = {target_id: target.id, config_revision: revision, slot_revision: target.slot_revision, started_at: now - 5000, outcome: 'success', sent: 3, received: 3,
    details: {semantics: 'staged_probe_v2', probe_complete: true, connect_complete: true, connect_ms: 21, requested: 3, window_complete: true}};
  return {target: {id: target.id, slot: target.slot, family: target.family, protocol: target.protocol, slot_revision: target.slot_revision, status: 'active'}, now, resolution_ms: 300000, window: stats, stale: false,
    groups: [{semantics: 'staged_probe_v2', metric, points}], current: [{semantics: 'staged_probe_v2', metric, latest_probe: sample, stale: false, freshness_budget_ms: 76000}]};
}

// options.raw: the v4 response the Server gives; handlers answer the two writes.
function setup(options = {}) {
  const {doc, dialog} = dom(), requests = [], writes = [];
  let raw = clone(options.raw || load('v4-running')), gets = 0;
  const fetcher = async (url, init = {}) => {
    const method = init.method || 'GET'; requests.push({url, method, body: init.body ? JSON.parse(init.body) : null});
    const reply = (status, value) => ({ok: status >= 200 && status < 300, status, statusText: String(status), json: async () => value});
    if (url.endsWith('/v4/config') && method === 'GET' && options.readFail?.()) return reply(503, {error: {code: 'unavailable'}});
    if (url.endsWith('/v4/config') && method === 'GET' && options.readStatus) return reply(options.readStatus, {error: {code: 'client_outdated'}});
    if (url.endsWith('/v4/config') && method === 'GET') { const answer = clone(raw), hold = options.holdRead?.(gets++); if (hold) await hold; return reply(200, answer); }
    if (url.endsWith('/v4/config') && method === 'PUT') { writes.push({kind: 'save', body: JSON.parse(init.body)}); return (options.save || (() => reply(200, raw)))(JSON.parse(init.body), {reply, get raw() { return raw; }, set raw(v) { raw = v; }}); }
    if (url.endsWith('/v4/enabled') && method === 'PUT') { writes.push({kind: 'enable', body: JSON.parse(init.body)}); return (options.enable || (() => reply(200, raw)))(JSON.parse(init.body), {reply, get raw() { return raw; }, set raw(v) { raw = v; }}); }
    if (url.includes('card-history')) {
      const id = new URL(url, 'http://local').searchParams.get('target_id'), c = C.adapt(raw), target = c.targets.find(t => t.id === id);
      return target ? reply(200, options.history ? options.history(cardHistory(target)) : cardHistory(target)) : reply(404, {});
    }
    return reply(404, {});
  };
  class Plot { constructor(opts, data) { this.opts = opts; this.data = data; } destroy() {} setSize() {} }
  let configs = 0;
  const ui = UI.create({document: doc, coordinator: options.coordinator || null, fetcher, csrf: () => 'synthetic', state: State, management: Management, Plot, Observer: null, Resize: null, interval: () => 1, clear: () => {}, now: () => 1800000000000 + (options.clock?.() || 0), onConfig: () => { configs++; }});
  const agent = {agent_id: AGENT, name: '合成设备'}, node = ui.mount(agent); doc.body.append(node);
  const panel = () => doc.body.children.find(n => n.className === 'nq-overlay');
  const field = name => panel()?.querySelector(`[data-nq-field="${name}"]`);
  const byText = (root, text) => root.querySelectorAll('button').find(n => n.textContent === text);
  const type = (name, value) => { const f = field(name); f.value = value; f.dispatch('input'); return f; };
  const check = (name, on = true) => { const f = field(name); f.checked = on; f.dispatch('change'); return f; };
  const choose = (name, value) => { const f = field(name); f.value = value; f.dispatch('change'); return f; };
  return {ui, doc, dialog, node, agent, requests, writes, panel, field, byText, type, check, choose, setRaw: v => { raw = clone(v); }, raw: () => raw, configs: () => configs,
    async open() { ui.setVisible(AGENT, true); await flush(); node.querySelector('.nq-link').click(); await flush(); return panel(); }};
}

// Every element in the page, for the checks that no user text ever became markup.
const allowedTags = new Set(['SECTION', 'DIV', 'BUTTON', 'SPAN', 'SMALL', 'P', 'LABEL', 'INPUT', 'SELECT', 'OPTION', 'FIELDSET', 'LEGEND', 'H2', 'STRONG', 'OUTPUT', 'DIALOG', 'BODY']);
const tags = root => [root, ...root.all()].map(n => n.tagName);

module.exports = {C, UI, State, load, clone, flush, dom, setup, cardHistory, allowedTags, tags, AGENT, fixtureDir};
